  const held = processorState.retirement()
  if (held) {
    const cleanup = await revisions.retire(held.binding)
    if (!cleanup.ok) throw new Error(cleanup.error)
  }
}
await disposePublication()
if (outcome.status === "failed" && record.kind === "schedule") reportStopped(outcome.reason, { retainPlayback: true })

